// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Admin override a check conclusion
	// (POST /api/admin/checks/override)
	AdminChecksOverride(w http.ResponseWriter, r *http.Request)
	// Admin cancel a running execution
	// (POST /api/admin/executions/cancel)
	AdminExecutionsCancel(w http.ResponseWriter, r *http.Request)
	// Admin satisfy a gate target manually
	// (POST /api/admin/gates/satisfy)
	AdminGatesSatisfy(w http.ResponseWriter, r *http.Request)
	// Admin release a gate grant
	// (POST /api/admin/grants/release)
	AdminGrantsRelease(w http.ResponseWriter, r *http.Request)
	// List gate targets awaiting human action, across all PRs
	// (GET /api/approvals)
	ListApprovals(w http.ResponseWriter, r *http.Request)
	// List the apply-lock claims for an environment
	// (POST /api/claims/list)
	ListClaims(w http.ResponseWriter, r *http.Request)
	// Admin-release one stack's claim or all of a PR's claims
	// (POST /api/claims/release)
	ReleaseClaims(w http.ResponseWriter, r *http.Request)
	// Read one execution's full state
	// (GET /api/execution/{id})
	GetExecution(w http.ResponseWriter, r *http.Request, id string)
	// List executions, newest first
	// (GET /api/executions)
	ListExecutions(w http.ResponseWriter, r *http.Request, params ListExecutionsParams)
	// Record the terminal plan state
	// (POST /api/finalize)
	FinalizeExecution(w http.ResponseWriter, r *http.Request)
	// Apply-time, fail-closed gate pre-check
	// (POST /api/gate/check)
	CheckGate(w http.ResponseWriter, r *http.Request)
	// Revoke the grants requested for (pr, environment)
	// (POST /api/gate/revoke)
	RevokeGate(w http.ResponseWriter, r *http.Request)
	// Register an execution and its changed subgraph
	// (POST /api/init)
	InitExecution(w http.ResponseWriter, r *http.Request)
	// Get folded claim set for an environment
	// (GET /api/inspect/claims/{env})
	InspectClaims(w http.ResponseWriter, r *http.Request, env string)
	// Get ordered events for a stream
	// (GET /api/inspect/events/{stream})
	InspectEvents(w http.ResponseWriter, r *http.Request, stream string, params InspectEventsParams)
	// Get gate state explainer and reason trail
	// (GET /api/inspect/gate/{pr}/{env})
	InspectGate(w http.ResponseWriter, r *http.Request, pr int, env string)
	// List all recorded grants
	// (GET /api/inspect/grants)
	InspectGrants(w http.ResponseWriter, r *http.Request, params InspectGrantsParams)
	// System-wide overview of all active PR states
	// (GET /api/inspect/overview)
	InspectOverview(w http.ResponseWriter, r *http.Request)
	// Get applier-pool slot occupancy and waiting lists
	// (GET /api/inspect/pool)
	InspectPool(w http.ResponseWriter, r *http.Request)
	// Ingest a per-stack output chunk
	// (POST /api/logs)
	AppendLogs(w http.ResponseWriter, r *http.Request)
	// Narrate a lifecycle phase transition
	// (POST /api/phase)
	ReportPhase(w http.ResponseWriter, r *http.Request)
	// Read a pull request's identity and per-tier merge state
	// (GET /api/pr/{n})
	GetPR(w http.ResponseWriter, r *http.Request, n int)
	// Tick a single stack's status
	// (POST /api/update)
	UpdateStack(w http.ResponseWriter, r *http.Request)
}

