// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/admin/checks/override", wrapper.AdminChecksOverride)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/admin/executions/cancel", wrapper.AdminExecutionsCancel)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/admin/gates/satisfy", wrapper.AdminGatesSatisfy)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/admin/grants/release", wrapper.AdminGrantsRelease)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/approvals", wrapper.ListApprovals)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/claims/list", wrapper.ListClaims)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/claims/release", wrapper.ReleaseClaims)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/execution/{id}", wrapper.GetExecution)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/executions", wrapper.ListExecutions)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/finalize", wrapper.FinalizeExecution)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/gate/check", wrapper.CheckGate)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/gate/revoke", wrapper.RevokeGate)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/init", wrapper.InitExecution)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/inspect/claims/{env}", wrapper.InspectClaims)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/inspect/events/{stream}", wrapper.InspectEvents)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/inspect/gate/{pr}/{env}", wrapper.InspectGate)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/inspect/grants", wrapper.InspectGrants)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/inspect/overview", wrapper.InspectOverview)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/inspect/pool", wrapper.InspectPool)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/logs", wrapper.AppendLogs)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/phase", wrapper.ReportPhase)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/pr/{n}", wrapper.GetPR)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/update", wrapper.UpdateStack)

	return m
}
